"""Opt-in canaries for a configured OpenAI-compatible LLM gateway."""

from __future__ import annotations

import os

import pytest


pytestmark = pytest.mark.live_llm

PROFILES = (
    "arc3-opus-lc",
    "arc3-opus-lc-low",
    "arc3-gpt5.5",
    "arc3-flash",
)


def _require_gateway_environment() -> None:
    has_key = bool(
        os.getenv("LLM_API_KEY") or os.getenv("LLM_API_KEY_POOL")
    )
    if not os.getenv("LLM_BASE_URL") or not has_key:
        pytest.skip(
            "set LLM_BASE_URL and LLM_API_KEY or LLM_API_KEY_POOL"
        )


@pytest.mark.parametrize("profile", PROFILES)
def test_profile_returns_a_text_stream(profile: str):
    _require_gateway_environment()

    from arc_agi_3.llm_configs import register_arc3_llms
    from beam.chain import beam_chain, get_text

    register_arc3_llms()
    llm = beam_chain(profile)

    try:
        text = "".join(
            get_text(chunk)
            for chunk in llm.stream("Reply with exactly the word OK.")
        )
    except Exception as exc:
        raise AssertionError(
            f"{profile} live canary failed: {type(exc).__name__}"
        ) from None

    assert text.strip()

