from __future__ import annotations

import json
import re
from dataclasses import dataclass, field, replace
from pathlib import Path
from typing import Any

from arc_agi_3.arc_league.context_block_base import ContextBlock
from arc_agi_3.grid import Grid, KEYBOARD_FOOTER


_APPROVAL_RE = re.compile(
    r"Approval\s+(\d+)/(\d+):\s+(.+?)\s+→\s+\w+\s+\(next:\s+(.+)\)"
)
_REJECT_RE = re.compile(r"Multi-action rejected after (\d+) actions")
_STOP_RE = re.compile(r"Multi-action stopped: .* at action (\d+)/(\d+)")
_EVENT_AFTER_CHOSEN_ACTION_KEY = "event_after_chosen_action"
_EVENT_METADATA_SUFFIXES = (
    "frame_count",
    "source_frame_count",
    "frame_indices",
    "decimation",
    "reduced_frame_position",
    "reduced_frame_source_index",
)


def _parse_click_rc(action: str | None) -> tuple[int, int] | None:
    """Parse ``CLICK x y`` into ``(row, col)`` for click-target marking."""
    if not action or not action.startswith("CLICK "):
        return None
    parts = action.split()
    if len(parts) != 3:
        return None
    try:
        col, row = int(parts[1]), int(parts[2])
        return (row, col)
    except (ValueError, IndexError):
        return None


@dataclass
class DecisionBatch:
    start_step: int
    end_step: int
    actions: list[str]
    source: str

    @property
    def n_executed(self) -> int:
        return len(self.actions)


@dataclass
class StateActionContextArgs:
    step: int
    current_level: int
    current_grid_data: list[list[int]]
    current_actions_this_level: int
    include_grid: bool = True
    history_rows: list[dict] = field(default_factory=list)
    state_history_step_targets: tuple[int, ...] = field(default_factory=tuple)
    level_history_rows: list[dict] = field(default_factory=list)
    incoming_row: dict | None = None
    omitted_prefix_row: dict | None = None
    current_transition_notice: str | None = None
    history_k: int | list[int] = 1
    effective_history_k: int | list[int] = 1
    previous_batch_len: int = 1
    level_action_history_max_rows: int | None = 100
    is_multi_action_preview: bool = False
    show_action_sequence: bool = True
    history_rows_include_grid: bool | None = None
    history_rows_include_event_map: bool | None = None
    previous_event_frame_limit: int | None = None
    current_event_frame_limit: int | None = None
    history_rows_grid_omitted_notice: bool = True


def _heading(title: str) -> str:
    return f"═══ {title} ═══"


def _grid_text(
    grid_data: list[list[int]] | None,
    *,
    step: int | None,
    level: int | None,
    action: str | None = None,
) -> str:
    if grid_data is None:
        return "(grid not available)"
    click_rc = _parse_click_rc(action)
    return Grid(grid_data, step=step, level=level).render_text(click_rc=click_rc, add_header=False)


def _format_color_diff(unique_colors_delta: dict | None) -> str:
    ucd = unique_colors_delta or {}
    appeared = list(ucd.get("appeared", []) or [])
    disappeared = list(ucd.get("disappeared", []) or [])
    parts = [f"+{color}" for color in appeared] + [f"-{color}" for color in disappeared]
    return " ".join(parts) if parts else "—"


def _format_event_value(event_frame_count: int | None) -> str:
    n = int(event_frame_count or 0)
    if n == 0:
        return "—"
    return f"{n} frame{'s' if n != 1 else ''}"


def _spread_positions(n_items: int, limit: int) -> list[int]:
    if n_items <= 0 or limit <= 0:
        return []
    if n_items <= limit:
        return list(range(n_items))
    if limit == 1:
        return [0]
    return sorted({
        round(i * (n_items - 1) / (limit - 1))
        for i in range(limit)
    })


def _first_present(row: dict, names: tuple[str, ...]) -> Any:
    for name in names:
        value = row.get(name)
        if value is not None:
            return value
    return None


def _best_single_event_position(row: dict, event_frames: list) -> int:
    """Choose the most visible frame when only one event map is shown."""
    if not event_frames:
        return 0
    reduced_position = row.get("event_reduced_frame_position")
    try:
        reduced_position = int(reduced_position)
    except (TypeError, ValueError):
        reduced_position = None
    if (
        reduced_position is not None
        and 0 <= reduced_position < len(event_frames)
    ):
        return reduced_position
    reduced_source_index = row.get("event_reduced_frame_source_index")
    indices = row.get("event_frame_indices")
    if isinstance(indices, list) and reduced_source_index is not None:
        try:
            reduced_source_index = int(reduced_source_index)
            return indices.index(reduced_source_index)
        except (TypeError, ValueError):
            pass
    previous_anchor = _first_present(
        row,
        ("previous_grid", "prev_grid", "grid_before", "grid"),
    )
    next_anchor = _first_present(
        row,
        ("settled_grid", "next_grid", "grid_after"),
    )
    anchors = [anchor for anchor in (previous_anchor, next_anchor) if anchor is not None]
    if not anchors:
        return 0
    try:
        import numpy as _np

        anchor_arrs = [_np.asarray(anchor, dtype=int) for anchor in anchors]
        scores = [
            sum(
                int(_np.count_nonzero(_np.asarray(frame, dtype=int) != anchor_arr))
                for anchor_arr in anchor_arrs
            )
            for frame in event_frames
        ]
    except Exception:
        return 0
    return int(max(range(len(scores)), key=lambda i: scores[i])) if scores else 0


def _event_display_positions(row: dict, event_frames: list, limit: int | None) -> list[int]:
    if not event_frames:
        return []
    if limit is None:
        return list(range(len(event_frames)))
    try:
        limit = int(limit)
    except (TypeError, ValueError):
        return list(range(len(event_frames)))
    if limit <= 0:
        return []
    if len(event_frames) <= limit:
        return list(range(len(event_frames)))
    if limit == 1:
        return [_best_single_event_position(row, event_frames)]
    return _spread_positions(len(event_frames), limit)


def _event_label(
    row: dict,
    position: int,
    sample_count: int,
    *,
    display_index: int | None = None,
    display_count: int | None = None,
) -> str:
    if display_index is None:
        display_index = position
    if display_count is None:
        display_count = sample_count
    indices = row.get("event_frame_indices")
    source_count = row.get("event_source_frame_count")
    has_source_metadata = (
        isinstance(indices, list)
        and len(indices) == sample_count
        and source_count is not None
    )
    if not has_source_metadata:
        return f"Event Frame {position + 1}/{sample_count}:"
    try:
        source_idx = int(indices[position])
        source_total = int(source_count)
    except (TypeError, ValueError, IndexError):
        return f"Event Frame {position + 1}/{sample_count}:"
    return f"Event Frame {source_idx}/{source_total}:"


def _event_view(row: dict, event_key: str) -> dict:
    if event_key == "event":
        return row
    view = dict(row)
    view["event"] = row.get(event_key) or []
    for suffix in _EVENT_METADATA_SUFFIXES:
        view[f"event_{suffix}"] = row.get(f"{event_key}_{suffix}")
    return view


def _event_count_text(row: dict, *, event_key: str = "event") -> str:
    view = _event_view(row, event_key)
    sample_count = len(view.get("event") or [])
    source_count = view.get("event_source_frame_count")
    try:
        source_count = int(source_count or 0)
    except (TypeError, ValueError):
        source_count = 0
    if source_count > sample_count:
        return f"{source_count} source frames"
    count = int(view.get("event_frame_count", sample_count) or sample_count)
    return f"{count} frame{'s' if count != 1 else ''}"


def _event_text(
    row: dict,
    *,
    event_frame_limit: int | None = None,
    event_key: str = "event",
) -> str | None:
    """Render event frame sequence as text."""
    row = _event_view(row, event_key)
    event_frames = row.get("event") or []
    if not event_frames:
        return None
    step = int(row.get("step", 0))
    level = int(row.get("level", 0))
    positions = _event_display_positions(row, event_frames, event_frame_limit)
    if not positions:
        return None
    lines = []
    for display_i, frame_pos in enumerate(positions):
        frame_data = event_frames[frame_pos]
        if display_i > 0:
            lines.append("")
        lines.append(
            _event_label(
                row,
                frame_pos,
                len(event_frames),
                display_index=display_i,
                display_count=len(positions),
            )
        )
        lines.append(Grid(frame_data, step=step, level=level).render_text(add_header=False))
    return "\n".join(lines)


def _final_event_text(row: dict, *, event_frame_limit: int | None = None) -> str | None:
    final_event = row.get("final_event")
    if not final_event:
        return None
    step = int(row.get("step", 0))
    level = int(row.get("level", 0))
    positions = _event_display_positions(row, final_event, event_frame_limit)
    if not positions:
        return None
    lines = []
    for display_i, frame_pos in enumerate(positions):
        if display_i > 0:
            lines.append("")
        lines.append(
            f"Final Event Frame {frame_pos + 1}/{len(final_event)}:"
        )
        lines.append(
            Grid(final_event[frame_pos], step=step, level=level).render_text(
                add_header=False,
            )
        )
    return "\n".join(lines)


def _transition_label(row: dict) -> str:
    from_step, to_step = _transition_bounds(row)
    return f"Step {from_step} -> Step {to_step}"


def _is_observation_state_row(row: dict | None) -> bool:
    return bool(
        isinstance(row, dict)
        and (
            "producer_transition_step" in row
            or "outgoing_action" in row
        )
    )


def _observation_incoming_bounds(row: dict) -> tuple[int | None, int]:
    to_step = int(row.get("step", 0))
    from_step = row.get("producer_transition_step")
    if from_step is None:
        return None, to_step
    return int(from_step), to_step


def _outgoing_action(row: dict) -> str | None:
    action = row.get("outgoing_action")
    if action is None:
        action = row.get("outgoing_transition_action")
    if action is None and not _is_observation_state_row(row):
        action = row.get("action_chosen", row.get("action"))
    if action is None:
        return None
    action = str(action)
    return action if action.strip() else None


def row_is_game_over(row: dict) -> bool:
    if row.get("game_over"):
        return True
    for key in ("event", "state", "outcome"):
        value = row.get(key)
        if (
            isinstance(value, str)
            and "GAME_OVER" in value.upper().replace("-", "_")
        ):
            return True
    return False


_row_is_game_over = row_is_game_over


def _game_over_action(row: dict) -> str | None:
    action = None
    if _is_observation_state_row(row):
        action = row.get("producer_action") or row.get("incoming_action")
    else:
        action = row.get("action_chosen", row.get("action"))
    if action is None:
        return None
    text = str(action).strip()
    return text or None


def _game_over_line(row: dict) -> str:
    details = []
    action = _game_over_action(row)
    if action:
        details.append(f"after {action}")
    if _is_observation_state_row(row):
        from_step, to_step = _observation_incoming_bounds(row)
        if from_step is not None:
            details.append(f"(Step {from_step} -> Step {to_step})")
    suffix = f" {' '.join(details)}" if details else ""
    return f"**GAME-OVER** - terminal/loss state{suffix}."


def _level_change_label(row: dict) -> str:
    level = int(row.get("level", 0))
    return f"Level Change: {level} -> {level + 1}"


def _render_transition_lines(
    row: dict, *, prefix: str = "", include_event_map: bool = True,
    event_frame_limit: int | None = None,
) -> list[str]:
    lines: list[str] = []
    if row.get("level_completed"):
        lines.append(f"{prefix}{_level_change_label(row)}")
        return lines

    transition = _transition_label(row)
    event_key = _EVENT_AFTER_CHOSEN_ACTION_KEY
    if include_event_map:
        event_text = _event_text(
            row,
            event_frame_limit=event_frame_limit,
            event_key=event_key,
        )
        if event_text is not None:
            lines.append(f"{prefix}{transition} Event:")
            lines.append(event_text)
        elif row.get(f"{event_key}_frame_count", 0):
            lines.append(
                f"{prefix}{transition} Event: "
                f"{_event_count_text(row, event_key=event_key)}"
            )

    diff = row.get("diff_pixels")
    if diff is not None:
        lines.append(f"{prefix}{transition} Pixel Diff: {diff}")

    color_diff = _format_color_diff(row.get("unique_colors_delta"))
    lines.append(f"{prefix}{transition} Color Diff: {color_diff}")
    return lines


def _render_observation_incoming_lines(
    row: dict,
    *,
    include_event_map: bool = True,
    event_frame_limit: int | None = None,
) -> list[str]:
    lines: list[str] = []
    from_step, to_step = _observation_incoming_bounds(row)

    if include_event_map:
        event_text = _event_text(row, event_frame_limit=event_frame_limit)
        if event_text is not None:
            lines.append(event_text)
            lines.append("")
        elif row.get("event_frame_count", 0):
            lines.append(f"Event Frames: {_event_count_text(row)}")

    if from_step is not None:
        transition = f"Step {from_step} -> Step {to_step}"
        diff = row.get("diff_pixels")
        if diff is not None:
            lines.append(f"{transition} Pixel Diff: {diff}")
        color_diff = _format_color_diff(row.get("unique_colors_delta"))
        lines.append(f"{transition} Color Diff: {color_diff}")
    return lines


def _render_final_state_row(
    grid_data: list[list[int]],
    *,
    action: str,
    step: int,
    level: int,
    show_action_sequence: bool = True,
) -> str:
    """Render the final state of a completed level (post-action, pre-transition)."""
    click_rc = _parse_click_rc(action) if show_action_sequence else None
    grid_text = Grid(grid_data, step=step, level=level).render_text(
        click_rc=click_rc, add_header=False,
    )
    lines = [
        f"### Final State (Level {level} completed)",
        grid_text,
        "",
        "Level Change: {} -> {}".format(level, level + 1),
    ]
    if show_action_sequence:
        lines.insert(3, f"Completing action: {action}")
    return "\n".join(lines)


def _render_observation_state_row(
    row: dict,
    *,
    include_grid: bool = True,
    include_event_map: bool | None = None,
    event_frame_limit: int | None = None,
    grid_omitted_notice: bool = True,
    show_action_sequence: bool = True,
) -> str:
    step = int(row["step"])
    level = row.get("level", "?")
    lines = [f"### Step {step} (Level {level})", ""]
    if include_event_map is None:
        include_event_map = include_grid
    lines.extend(
        _render_observation_incoming_lines(
            row,
            include_event_map=include_event_map,
            event_frame_limit=event_frame_limit,
        )
    )
    if _row_is_game_over(row):
        lines.append(_game_over_line(row))
    if lines[-1] != "":
        lines.append("")
    if include_grid:
        lines.append("Grid:")
        lines.append(
            _grid_text(
                row.get("grid"),
                step=step,
                level=row.get("level"),
                action=_outgoing_action(row) if show_action_sequence else None,
            )
        )
    elif grid_omitted_notice:
        lines.append("(grid omitted)")
    if show_action_sequence:
        action = _outgoing_action(row)
        if action is not None:
            lines.extend(["", f"Action taken: {action}"])
    return "\n".join(lines).rstrip()


def _render_state_row(
    row: dict,
    *,
    include_grid: bool = True,
    include_event_map: bool | None = None,
    event_frame_limit: int | None = None,
    grid_omitted_notice: bool = True,
    show_action_sequence: bool = True,
) -> str:
    step = int(row["step"])
    level = row.get("level", "?")
    diff = row.get("diff_pixels")
    color_delta = row.get("unique_colors_delta") or {}
    appeared = color_delta.get("appeared", [])
    new_colors = ",".join(appeared) if appeared else ""
    meta_parts = [f"diff={diff}"] if diff is not None else []
    if new_colors:
        meta_parts.append(f"new_colors={new_colors}")
    meta_str = f" {' '.join(meta_parts)}" if meta_parts else ""
    lines = [f"### Step {step} (Level {level}){meta_str}"]
    if include_grid:
        lines.append(
            _grid_text(
                row.get("grid"),
                step=step,
                level=row.get("level"),
                action=(
                    row.get("action_chosen")
                    if show_action_sequence else None
                ),
            )
        )
    elif grid_omitted_notice:
        lines.append("(grid omitted)")
    if show_action_sequence:
        lines.extend(
            [
                "",
                f"Action taken: {row.get('action_chosen', row.get('action', '?'))}",
            ]
        )
    if _row_is_game_over(row):
        if row.get("game_over_recovered"):
            lines.append(
                "**GAME-OVER** - auto-recovered via RESET (level restarted)."
            )
        else:
            lines.append(_game_over_line(row))
    if include_event_map is None:
        include_event_map = include_grid
    lines.extend(
        _render_transition_lines(
            row,
            include_event_map=include_event_map,
            event_frame_limit=event_frame_limit,
        )
    )
    return "\n".join(lines)


def _render_current_observation_state(args: StateActionContextArgs) -> str:
    row = dict(args.incoming_row or {})
    row.setdefault("step", args.step)
    row.setdefault("level", args.current_level)
    row.setdefault("grid", args.current_grid_data)
    lines = [f"### Step {args.step} (Level {args.current_level}, Current Step)", ""]
    include_event_map = args.include_grid or bool(args.current_event_frame_limit)
    lines.extend(
        _render_observation_incoming_lines(
            row,
            include_event_map=include_event_map,
            event_frame_limit=args.current_event_frame_limit,
        )
    )
    if _row_is_game_over(row):
        lines.append(_game_over_line(row))
    if lines[-1] != "":
        lines.append("")
    if args.include_grid:
        lines.append("Grid:")
        lines.append(
            _grid_text(
                row.get("grid", args.current_grid_data),
                step=args.step,
                level=args.current_level,
            )
        )
        if Grid._default_add_grid_orientation:
            lines.append(KEYBOARD_FOOTER)
    else:
        lines.append("(grid omitted)")
    return "\n".join(lines).rstrip()


def _render_current_state(args: StateActionContextArgs) -> str:
    if _is_observation_state_row(args.incoming_row):
        return _render_current_observation_state(args)
    grid_line = (
        _grid_text(
            args.current_grid_data,
            step=args.step,
            level=args.current_level,
        )
        if args.include_grid else "(grid omitted)"
    )
    lines = [
        f"### Step {args.step} (Level {args.current_level}, Current Step)",
        grid_line,
    ]
    if args.include_grid and Grid._default_add_grid_orientation:
        lines.append(KEYBOARD_FOOTER)
    return "\n".join(lines)


def _render_action_level_table(
    rows: list[dict],
    *,
    start_index: int = 1,
) -> list[str]:
    lines = [
        "| From Step | Action | To Step | Event Frames | Pixel Diff | Color Diff |",
        "|-----------|--------|---------|--------------|------------|------------|",
    ]
    for row in rows:
        from_step, to_step = _transition_bounds(row)
        action = _row_action(row) or "?"
        event_value = _format_event_value(
            row.get(f"{_EVENT_AFTER_CHOSEN_ACTION_KEY}_frame_count", 0)
        )
        # Special events: GAME_OVER, level completion
        if _row_is_game_over(row):
            event_value = (
                "GAME-OVER -> LEVEL_RESET"
                if row.get("game_over_recovered")
                else "GAME-OVER"
            )
        elif row.get("level_completed"):
            final_event_count = len(row.get("final_event") or [])
            if final_event_count:
                event_value = (
                    f"✓LEVEL_UP; final_event "
                    f"{_format_event_value(final_event_count)}"
                )
            else:
                event_value = "✓LEVEL_UP"
        pixel_diff = "—" if row.get("diff_pixels") is None else str(row.get("diff_pixels"))
        color_diff = _format_color_diff(row.get("unique_colors_delta"))
        lines.append(
            f"| {from_step} | {action} | {to_step} | {event_value} | {pixel_diff} | {color_diff} |"
        )
    return lines


def _transition_bounds(row: dict) -> tuple[int, int]:
    from_step = row.get(
        "from_global_step",
        row.get("from_step", row.get("step")),
    )
    if from_step is None:
        from_step = 0
    from_step = int(from_step)
    to_step = row.get(
        "to_global_step",
        row.get("to_step", from_step + 1),
    )
    return from_step, int(to_step)


def _row_action(row: dict) -> str | None:
    action = row.get("action_chosen", row.get("action"))
    if action is None:
        return None
    return str(action)


def _dedupe_action_rows(rows: list[dict]) -> list[dict]:
    filtered_rows = []
    seen_transitions = set()
    for row in rows:
        if not _row_action(row):
            continue
        transition = _transition_bounds(row)
        if transition in seen_transitions:
            continue
        seen_transitions.add(transition)
        filtered_rows.append(row)
    return filtered_rows


def _reset_epoch_rows(
    rows: list[dict],
    *,
    current_step: int,
) -> tuple[list[dict], str | None]:
    reset_boundary: tuple[int, int] | None = None
    for row in rows:
        if _row_action(row) != "RESET":
            continue
        from_step, to_step = _transition_bounds(row)
        if to_step > current_step:
            continue
        if (
            reset_boundary is None
            or (to_step, from_step) > (reset_boundary[1], reset_boundary[0])
        ):
            reset_boundary = (from_step, to_step)

    if reset_boundary is None:
        return rows, None

    from_step, to_step = reset_boundary
    epoch_rows = [
        row for row in rows
        if _transition_bounds(row)[0] >= to_step
    ]
    notice = f"History starts after RESET at Step {from_step} -> Step {to_step}."
    return epoch_rows, notice


class StateHistory(ContextBlock):
    def __init__(self, name: str = "state_history"):
        super().__init__(name, self._render_state_history)

    @staticmethod
    def _event_frame_limit_for_row(
        args: StateActionContextArgs,
        row: dict,
    ) -> int | None:
        if _is_observation_state_row(row):
            return (
                args.current_event_frame_limit
                if int(row.get("step", -1)) == int(args.step)
                else args.previous_event_frame_limit
            )
        _from_step, to_step = _transition_bounds(row)
        return (
            args.current_event_frame_limit
            if to_step == args.step
            else args.previous_event_frame_limit
        )

    @staticmethod
    def _render_state_history(args: StateActionContextArgs) -> str | None:
        lines = [_heading("State History"), ""]
        history_include_grid = (
            args.include_grid
            if args.history_rows_include_grid is None
            else args.history_rows_include_grid
        )
        history_include_event_map = (
            history_include_grid
            if args.history_rows_include_event_map is None
            else args.history_rows_include_event_map
        )
        if args.current_transition_notice:
            lines.append(args.current_transition_notice)
            lines.append("")
        if args.omitted_prefix_row is not None:
            omitted_renderer = (
                _render_observation_state_row
                if _is_observation_state_row(args.omitted_prefix_row)
                else _render_state_row
            )
            lines.append(
                omitted_renderer(
                    args.omitted_prefix_row,
                    include_grid=False,
                    event_frame_limit=StateHistory._event_frame_limit_for_row(
                        args,
                        args.omitted_prefix_row,
                    ),
                    show_action_sequence=args.show_action_sequence,
                )
            )
            lines.append("")
        for row in args.history_rows:
            event_frame_limit = StateHistory._event_frame_limit_for_row(args, row)
            row_renderer = (
                _render_observation_state_row
                if _is_observation_state_row(row)
                else _render_state_row
            )
            lines.append(
                row_renderer(
                    row,
                    include_grid=history_include_grid,
                    include_event_map=history_include_event_map,
                    event_frame_limit=event_frame_limit,
                    grid_omitted_notice=args.history_rows_grid_omitted_notice,
                    show_action_sequence=args.show_action_sequence,
                )
            )
            lines.append("")
        lines.append(_render_current_state(args))
        return "\n".join(lines).strip()


def render_action_level_history_rows(
    rows: list[dict],
    *,
    current_level: int,
    max_rows: int | None = 100,
    title: str | None = None,
) -> str:
    filtered_rows = _dedupe_action_rows(rows)
    total_rows = len(filtered_rows)
    if title is None:
        if max_rows is not None and max_rows > 0 and total_rows > max_rows:
            title = (
                f"Level {current_level} Action History "
                f"(showing last {min(max_rows, total_rows)} of {total_rows} actions)"
            )
        else:
            title = f"Level {current_level} Action History ({total_rows} actions)"

    lines = [_heading(title), ""]
    if not filtered_rows:
        lines.append("(no actions yet in this level)")
        return "\n".join(lines).strip()

    lines.extend([
        "Each row is one action transition. Action is applied at From Step; To Step is the resulting stable grid.",
        "",
    ])

    if max_rows is not None and max_rows > 0 and total_rows > max_rows:
        shown_rows = filtered_rows[-max_rows:]
        start_index = total_rows - len(shown_rows) + 1
    else:
        shown_rows = filtered_rows
        start_index = 1

    lines.extend(_render_action_level_table(shown_rows, start_index=start_index))
    return "\n".join(lines).strip()


class ActionLevelHistory(ContextBlock):
    def __init__(self, name: str = "action_level_history"):
        super().__init__(name, self._render_action_level_history)

    @staticmethod
    def _render_action_level_history(args: StateActionContextArgs) -> str | None:
        return render_action_level_history_rows(
            args.level_history_rows,
            current_level=args.current_level,
            max_rows=args.level_action_history_max_rows,
        )


def _select_sparse(rows: list, selector: list[int]) -> list:
    """Select rows at sparse offsets from tail (same as FileBlock._select_tail_sections)."""
    indices = sorted({len(rows) - o for o in selector if 0 < o <= len(rows)})
    return [rows[i] for i in indices]


def build_context_args_from_action_history(
    action_history: list[dict],
    *,
    current_step: int,
    current_level: int,
    current_grid_data: list[list[int]],
    current_actions_this_level: int,
    history_k: int | list[int],
    multi_action_history_k: int,
    multi_action_count: int = 0,
    level_completed: bool = False,
    level_action_history_max_rows: int | None = 100,
) -> StateActionContextArgs:
    # Multi-action override only applies to int selectors
    effective_history_k = history_k
    if isinstance(history_k, int) and multi_action_count > 1:
        effective_history_k = max(
            min(multi_action_history_k, multi_action_count),
            history_k,
        )

    level_rows = _dedupe_action_rows([
        row for row in action_history
        if int(row.get("level", -1)) == current_level
        and int(row.get("step", -1)) < current_step
    ])
    level_rows = [dict(row) for row in level_rows]
    state_history_rows, reset_boundary_notice = _reset_epoch_rows(
        level_rows,
        current_step=current_step,
    )

    if isinstance(effective_history_k, list):
        history_rows = _select_sparse(state_history_rows, effective_history_k)
    elif effective_history_k > 0:
        history_rows = state_history_rows[-effective_history_k:]
    else:
        history_rows = []

    omitted_prefix_row = None
    # omitted_prefix_row only makes sense for sequential windows
    if isinstance(effective_history_k, int):
        if history_rows:
            needed = len(history_rows) + 1
            if len(state_history_rows) >= needed:
                omitted_prefix_row = state_history_rows[-needed]
        elif effective_history_k <= 0 and state_history_rows:
            omitted_prefix_row = state_history_rows[-1]

    notices = []
    if reset_boundary_notice:
        notices.append(reset_boundary_notice)
    if level_completed:
        notices.append(f"Level Change: {current_level - 1} -> {current_level}")
    current_transition_notice = "\n\n".join(notices) if notices else None

    is_multi_preview = (
        isinstance(effective_history_k, int)
        and effective_history_k == 0
        and multi_action_count > 1
    )

    return StateActionContextArgs(
        step=current_step,
        current_level=current_level,
        current_grid_data=current_grid_data,
        current_actions_this_level=current_actions_this_level,
        history_rows=history_rows,
        state_history_step_targets=tuple(
            int(row["step"]) for row in history_rows if row.get("step") is not None
        ),
        level_history_rows=level_rows,
        incoming_row=level_rows[-1] if level_rows else None,
        omitted_prefix_row=omitted_prefix_row,
        current_transition_notice=current_transition_notice,
        history_k=history_k,
        effective_history_k=effective_history_k,
        previous_batch_len=multi_action_count if multi_action_count > 0 else 1,
        level_action_history_max_rows=level_action_history_max_rows,
        is_multi_action_preview=is_multi_preview,
    )


def _row_level_value(row: dict):
    return row.get("level", row.get("levels_completed"))


def _attach_outgoing_transition(
    observation: dict,
    transition: dict | None,
) -> dict:
    row = dict(observation)
    if transition is None:
        return row
    from_step, to_step = _transition_bounds(transition)
    action = _row_action(transition)
    row.update({
        "outgoing_action": action or "",
        "outgoing_transition_step": from_step,
        "outgoing_to_step": to_step,
    })
    return row


def build_context_args_from_observations_and_transitions(
    observations: list[dict],
    transitions: list[dict],
    *,
    current_step: int,
    current_level: int,
    current_grid_data: list[list[int]],
    current_actions_this_level: int,
    history_k: int | list[int],
    multi_action_history_k: int,
    multi_action_count: int = 0,
    level_completed: bool = False,
    level_action_history_max_rows: int | None = 100,
) -> StateActionContextArgs:
    effective_history_k = history_k
    if isinstance(history_k, int) and multi_action_count > 1:
        effective_history_k = max(
            min(multi_action_history_k, multi_action_count),
            history_k,
        )

    current_step = int(current_step)
    observation_by_step = {
        int(row["step"]): dict(row)
        for row in observations
        if isinstance(row, dict) and row.get("step") is not None
    }
    transition_rows = _dedupe_action_rows([
        dict(row)
        for row in transitions
        if isinstance(row, dict)
        and row.get("step", row.get("from_step")) is not None
    ])
    level_rows = [
        row for row in transition_rows
        if _row_level_value(row) == current_level
        and _transition_bounds(row)[0] < current_step
    ]
    state_transition_rows, reset_boundary_notice = _reset_epoch_rows(
        level_rows,
        current_step=current_step,
    )
    transition_by_from_step = {
        _transition_bounds(row)[0]: row
        for row in state_transition_rows
    }
    state_history_rows = []
    for step, transition in sorted(transition_by_from_step.items()):
        observation = observation_by_step.get(step)
        if observation is None:
            raise ValueError(f"StateHistory missing observation row for step {step}")
        state_history_rows.append(
            _attach_outgoing_transition(observation, transition)
        )

    if isinstance(effective_history_k, list):
        history_rows = _select_sparse(state_history_rows, effective_history_k)
    elif effective_history_k > 0:
        history_rows = state_history_rows[-effective_history_k:]
    else:
        history_rows = []

    omitted_prefix_row = None
    if isinstance(effective_history_k, int):
        if history_rows:
            needed = len(history_rows) + 1
            if len(state_history_rows) >= needed:
                omitted_prefix_row = state_history_rows[-needed]
        elif effective_history_k <= 0 and state_history_rows:
            omitted_prefix_row = state_history_rows[-1]

    notices = []
    if reset_boundary_notice:
        notices.append(reset_boundary_notice)
    if level_completed:
        notices.append(f"Level Change: {current_level - 1} -> {current_level}")
    current_transition_notice = "\n\n".join(notices) if notices else None

    current_observation = dict(observation_by_step.get(current_step) or {
        "step": current_step,
        "grid": current_grid_data,
        "level": current_level,
        "event": [],
        "event_frame_count": 0,
        "event_source_frame_count": 0,
        "event_frame_indices": [],
        "producer_transition_step": None,
        "producer_action": "",
        "diff_pixels": None,
        "unique_colors_delta": {},
    })
    current_observation.setdefault("producer_transition_step", None)
    current_observation.setdefault("producer_action", "")
    current_observation.setdefault("level", current_level)
    current_observation.setdefault("grid", current_grid_data)

    is_multi_preview = (
        isinstance(effective_history_k, int)
        and effective_history_k == 0
        and multi_action_count > 1
    )

    return StateActionContextArgs(
        step=current_step,
        current_level=current_level,
        current_grid_data=current_observation.get("grid", current_grid_data),
        current_actions_this_level=current_actions_this_level,
        history_rows=history_rows,
        state_history_step_targets=tuple(
            int(row["step"]) for row in history_rows if row.get("step") is not None
        ),
        level_history_rows=level_rows,
        incoming_row=current_observation,
        omitted_prefix_row=omitted_prefix_row,
        current_transition_notice=current_transition_notice,
        history_k=history_k,
        effective_history_k=effective_history_k,
        previous_batch_len=multi_action_count if multi_action_count > 0 else 1,
        level_action_history_max_rows=level_action_history_max_rows,
        is_multi_action_preview=is_multi_preview,
    )


def render_state_history_block(args: StateActionContextArgs) -> str:
    return StateHistory().render(args) or ""


def render_action_level_history_block(args: StateActionContextArgs) -> str:
    return ActionLevelHistory().render(args) or ""


def render_available_actions_block(available_actions: list[str]) -> str:
    if not available_actions:
        return ""
    actions = ["CLICK x y" if a == "CLICK" else a for a in available_actions]
    return _heading("Available Actions") + "\n" + ", ".join(actions)


def select_level_reflection_history_rows(
    level_entries: list[dict],
    *,
    history_k: int | list[int],
) -> list[dict]:
    """Return the action rows rendered in completed-level State History."""
    has_final = bool(
        level_entries and level_entries[-1].get("final_state") is not None
    )
    if isinstance(history_k, list):
        return _select_sparse(level_entries, history_k)
    n_history = history_k + 1 if not has_final else history_k
    return level_entries[-n_history:] if n_history > 0 else []


def level_reflection_state_history_step_targets(
    level_entries: list[dict],
    *,
    history_k: int | list[int],
) -> tuple[int, ...]:
    """Return env steps covered by completed-level State History rendering."""
    targets: list[int] = []
    for row in select_level_reflection_history_rows(
        level_entries, history_k=history_k,
    ):
        if row.get("step") is not None:
            targets.append(int(row["step"]))

    if level_entries and level_entries[-1].get("final_state") is not None:
        final_step = level_entries[-1].get("step")
        if final_step is not None:
            targets.append(int(final_step))

    return tuple(dict.fromkeys(targets))


def render_level_reflection_state_history(
    level_entries: list[dict],
    *,
    completed_level: int,
    history_k: int | list[int],
    include_grid: bool = True,
    show_action_sequence: bool = True,
    event_frame_limit: int | None = None,
    history_event_frame_limit: int | None = None,
    final_event_frame_limit: int | None = None,
) -> str:
    history_limit = (
        history_event_frame_limit
        if history_event_frame_limit is not None
        else event_frame_limit
    )
    final_limit = (
        final_event_frame_limit
        if final_event_frame_limit is not None
        else event_frame_limit
    )
    has_final = level_entries and level_entries[-1].get("final_state") is not None
    history_rows = select_level_reflection_history_rows(
        level_entries, history_k=history_k,
    )
    lines = [_heading("State History"), ""]
    for row in history_rows:
        lines.append(
            _render_state_row(
                row,
                include_grid=include_grid,
                event_frame_limit=history_limit,
                show_action_sequence=show_action_sequence,
            )
        )
        lines.append("")
    if has_final:
        last = level_entries[-1]
        action = last.get("action_chosen", last.get("action", "?"))
        step = int(last.get("step", 0))
        final_event_text = _final_event_text(
            last,
            event_frame_limit=final_limit,
        )
        if final_event_text is not None:
            lines.append("### Final Event")
            lines.append(final_event_text)
            lines.append("")
        lines.append(_render_final_state_row(
            last["final_state"],
            action=action,
            step=step,
            level=completed_level,
            show_action_sequence=show_action_sequence,
        ))
        lines.append("")
    return "\n".join(lines).strip()


def render_level_reflection_context(
    step_log: list[dict],
    completed_step: int,
    *,
    history_k: int | list[int],
    level_action_history_max_rows: int | None = 100,
    event_frame_limit: int | None = None,
    history_event_frame_limit: int | None = None,
    final_event_frame_limit: int | None = None,
) -> str:
    history_limit = (
        history_event_frame_limit
        if history_event_frame_limit is not None
        else event_frame_limit
    )
    final_limit = (
        final_event_frame_limit
        if final_event_frame_limit is not None
        else event_frame_limit
    )
    completed_row = step_log[completed_step]
    completed_level = int(completed_row.get("level", 0))
    level_rows = [
        row for row in step_log
        if int(row.get("level", -1)) == completed_level
        and int(row.get("step", -1)) <= completed_step
    ]
    # Check if the completing step has a final_state (post-action, pre-transition grid)
    has_final_state = completed_row.get("final_state") is not None

    if isinstance(history_k, list):
        history_rows = _select_sparse(level_rows, history_k)
    else:
        # If we have a final state, take one fewer history row to make room
        n_history = history_k + 1 if not has_final_state else history_k
        history_rows = level_rows[-n_history:]

    lines = [
        _heading(f"Level Reflection — Level {completed_level} Completed"),
        "",
        _heading("State History"),
        "",
    ]
    for row in history_rows:
        lines.append(
            _render_state_row(row, event_frame_limit=history_limit)
        )
        lines.append("")

    # Add final state grid — the post-action result of the level-completing move
    if has_final_state:
        action = completed_row.get("action_chosen", completed_row.get("action", "?"))
        step = int(completed_row.get("step", 0))
        final_event_text = _final_event_text(
            completed_row,
            event_frame_limit=final_limit,
        )
        if final_event_text is not None:
            lines.append("### Final Event")
            lines.append(final_event_text)
            lines.append("")
        lines.append(_render_final_state_row(
            completed_row["final_state"],
            action=action,
            step=step,
            level=completed_level,
        ))
        lines.append("")

    total_rows = len(level_rows)
    max_rows = level_action_history_max_rows
    if max_rows is not None and max_rows > 0 and total_rows > max_rows:
        shown_rows = level_rows[-max_rows:]
        start_index = total_rows - len(shown_rows) + 1
        title = (
            f"Level {completed_level} Action History "
            f"(showing last {len(shown_rows)} of {total_rows} actions)"
        )
    else:
        shown_rows = level_rows
        start_index = 1
        title = f"Level {completed_level} Action History ({total_rows} actions)"
    lines.extend([_heading(title), ""])
    lines.extend(_render_action_level_table(shown_rows, start_index=start_index))
    return "\n".join(lines).strip() + "\n"


def _load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text())


def _parse_visible_batches(json_log_path: Path) -> list[list[str]]:
    batches: list[list[str]] = []
    current: dict[str, Any] | None = None

    for raw_line in json_log_path.read_text().splitlines():
        line = raw_line.strip()
        if not line or line == "JSON LOGGER":
            continue
        try:
            payload = json.loads(line)
        except json.JSONDecodeError:
            continue
        msg = payload.get("record", {}).get("message", "")

        match = _APPROVAL_RE.search(msg)
        if match:
            idx = int(match.group(1))
            denom = int(match.group(2))
            action = match.group(3).strip()
            next_action = match.group(4).strip()
            if idx == 1:
                if current is not None:
                    if current.get("last_next_action") and len(current["actions"]) < current["proposed"]:
                        current["actions"].append(current["last_next_action"])
                    batches.append(current["actions"])
                current = {"proposed": denom + 1, "actions": [], "last_next_action": None}
            if current is None:
                continue
            current["actions"].append(action)
            current["last_next_action"] = next_action
            continue

        match = _REJECT_RE.search(msg)
        if match and current is not None:
            batches.append(current["actions"])
            current = None
            continue

        match = _STOP_RE.search(msg)
        if match and current is not None:
            executed = int(match.group(1))
            if current.get("last_next_action") and len(current["actions"]) < executed:
                current["actions"].append(current["last_next_action"])
            batches.append(current["actions"])
            current = None

    if current is not None:
        if current.get("last_next_action") and len(current["actions"]) < current["proposed"]:
            current["actions"].append(current["last_next_action"])
        batches.append(current["actions"])

    return batches


def reconstruct_decision_batches(
    step_log: list[dict],
    json_log_path: Path,
) -> list[DecisionBatch]:
    visible_batches = _parse_visible_batches(json_log_path)
    actions = [row.get("action_chosen", row.get("action", "")) for row in step_log]

    cursor = 0
    batches: list[DecisionBatch] = []

    for seq in visible_batches:
        found = None
        for i in range(cursor, len(actions) - len(seq) + 1):
            if actions[i:i + len(seq)] == seq:
                found = i
                break
        if found is None:
            raise ValueError(f"Could not align logged batch: {seq!r}")

        while cursor < found:
            batches.append(
                DecisionBatch(
                    start_step=cursor + 1,
                    end_step=cursor + 1,
                    actions=[actions[cursor]],
                    source="single",
                )
            )
            cursor += 1

        batches.append(
            DecisionBatch(
                start_step=found + 1,
                end_step=found + len(seq),
                actions=list(seq),
                source="logged" if len(seq) > 1 else "single_logged",
            )
        )
        cursor = found + len(seq)

    while cursor < len(actions):
        batches.append(
            DecisionBatch(
                start_step=cursor + 1,
                end_step=cursor + 1,
                actions=[actions[cursor]],
                source="single",
            )
        )
        cursor += 1

    return batches


def configure_grid_from_manifest(manifest: dict[str, Any]) -> None:
    config = manifest.get("config", {})
    Grid.configure(
        sep=config.get("grid_sep", ""),
        fmt=config.get("grid_format", "hex"),
        enumerate_rows=str(config.get("grid_enumerate_rows", "False")) == "True",
        enumerate_cols=str(config.get("grid_enumerate_cols", "False")) == "True",
        mark_click=str(config.get("mark_click_target", "False")) == "True",
    )


def _build_context_args_for_step(
    step_log: list[dict],
    current_step: int,
    *,
    history_k: int | list[int],
    effective_history_k: int | list[int],
    previous_batch_len: int = 1,
    is_multi_action_preview: bool = False,
    level_action_history_max_rows: int | None = 100,
) -> StateActionContextArgs:
    row = step_log[current_step]
    current_level = int(row.get("level", 0))
    current_actions_this_level = sum(
        1
        for prev in step_log[:current_step]
        if int(prev.get("level", -1)) == current_level
        and prev.get("action_chosen", prev.get("action")) != "RESET"
    )

    level_history_rows = _dedupe_action_rows([
        prev
        for prev in step_log[: current_step]
        if int(prev.get("level", -1)) == current_level
        and int(prev.get("step", -1)) < current_step
    ])
    state_history_rows, reset_boundary_notice = _reset_epoch_rows(
        level_history_rows,
        current_step=current_step,
    )

    if isinstance(effective_history_k, list):
        history_rows = _select_sparse(state_history_rows, effective_history_k)
    else:
        history_rows = (
            state_history_rows[-effective_history_k:]
            if effective_history_k > 0
            else []
        )

    incoming_row = step_log[current_step - 1] if current_step > 0 else None
    omitted_prefix_row = None
    current_transition_notice = None
    # omitted_prefix_row only for sequential mode
    if isinstance(effective_history_k, int):
        if history_rows:
            index = state_history_rows.index(history_rows[0])
            if index > 0:
                omitted_prefix_row = state_history_rows[index - 1]
        elif effective_history_k <= 0 and state_history_rows:
            omitted_prefix_row = state_history_rows[-1]

    notices = []
    if reset_boundary_notice:
        notices.append(reset_boundary_notice)
    if not history_rows and incoming_row is not None and incoming_row.get("level_completed"):
        notices.append(_level_change_label(incoming_row))
    current_transition_notice = "\n\n".join(notices) if notices else None

    return StateActionContextArgs(
        step=current_step,
        current_level=current_level,
        current_grid_data=row.get("grid"),
        current_actions_this_level=current_actions_this_level,
        history_rows=history_rows,
        state_history_step_targets=tuple(
            int(row["step"]) for row in history_rows if row.get("step") is not None
        ),
        level_history_rows=level_history_rows,
        incoming_row=incoming_row,
        omitted_prefix_row=omitted_prefix_row,
        current_transition_notice=current_transition_notice,
        history_k=history_k,
        effective_history_k=effective_history_k,
        previous_batch_len=previous_batch_len,
        level_action_history_max_rows=level_action_history_max_rows,
        is_multi_action_preview=is_multi_action_preview,
    )


def build_context_args_for_batch(
    step_log: list[dict],
    batch_index: int,
    batches: list[DecisionBatch],
    *,
    history_k: int | list[int],
    multi_action_history_k: int,
    force_history_k: int | None = None,
    level_action_history_max_rows: int | None = 100,
) -> StateActionContextArgs:
    batch = batches[batch_index]

    previous_batch_len = batches[batch_index - 1].n_executed if batch_index > 0 else 1
    effective_history_k = history_k
    # Multi-action override only applies to int selectors
    if isinstance(history_k, int) and batch_index > 0 and previous_batch_len > 1:
        effective_history_k = max(
            min(multi_action_history_k, previous_batch_len),
            history_k,
        )
    if force_history_k is not None:
        effective_history_k = force_history_k

    return _build_context_args_for_step(
        step_log,
        batch.start_step,
        history_k=history_k,
        effective_history_k=effective_history_k,
        previous_batch_len=previous_batch_len,
        is_multi_action_preview=force_history_k == 0 and batch.n_executed > 1,
        level_action_history_max_rows=level_action_history_max_rows,
    )


def build_context_args_for_multi_action_step(
    step_log: list[dict],
    current_step: int,
    *,
    history_k: int,
    level_action_history_max_rows: int | None = 100,
) -> StateActionContextArgs:
    return _build_context_args_for_step(
        step_log,
        current_step,
        history_k=history_k,
        effective_history_k=0,
        previous_batch_len=1,
        is_multi_action_preview=True,
        level_action_history_max_rows=level_action_history_max_rows,
    )


def render_context_pair(args: StateActionContextArgs) -> str:
    state_history = StateHistory().render(args) or ""
    action_level_history = ActionLevelHistory().render(args) or ""
    return f"{state_history}\n\n{action_level_history}\n".strip() + "\n"


def render_run_contexts(
    run_dir: str | Path,
    output_dir: str | Path,
) -> dict[str, str]:
    run_path = Path(run_dir)
    output_path = Path(output_dir)
    output_path.mkdir(parents=True, exist_ok=True)

    result = _load_json(run_path / "result.json")
    manifest = _load_json(run_path / "system" / "manifest.json")
    configure_grid_from_manifest(manifest)

    history_k = int(manifest["config"]["history_k"])
    multi_action_history_k = int(manifest["config"]["multi_action_history_k"])
    level_action_history_max_rows = int(manifest["config"].get("level_action_history_max_rows", 100))
    step_log = result["step_log"]
    batches = reconstruct_decision_batches(step_log, run_path / "system" / "json.log")

    rendered: dict[str, str] = {}
    for batch_index, batch in enumerate(batches):
        args = build_context_args_for_batch(
            step_log,
            batch_index,
            batches,
            history_k=history_k,
            multi_action_history_k=multi_action_history_k,
            level_action_history_max_rows=level_action_history_max_rows,
        )
        text = render_context_pair(args)
        key = f"step_{batch.start_step:04d}.md"
        rendered[key] = text
        (output_path / key).write_text(text)

        if batch.n_executed > 1:
            for current_step in range(batch.start_step + 1, batch.end_step + 1):
                ma_args = build_context_args_for_multi_action_step(
                    step_log,
                    current_step,
                    history_k=history_k,
                    level_action_history_max_rows=level_action_history_max_rows,
                )
                ma_text = render_context_pair(ma_args)
                ma_key = f"step_{current_step:04d}_ma.md"
                rendered[ma_key] = ma_text
                (output_path / ma_key).write_text(ma_text)

    level_reflection_keys: list[str] = []
    for row in step_log:
        if row.get("level_completed"):
            completed_step = int(row["step"])
            completed_level = int(row.get("level", 0))
            reflection_key = (
                f"step_{completed_step:04d}_level_reflection_{completed_level}.md"
            )
            reflection_text = render_level_reflection_context(
                step_log,
                completed_step,
                history_k=history_k,
                level_action_history_max_rows=level_action_history_max_rows,
            )
            rendered[reflection_key] = reflection_text
            (output_path / reflection_key).write_text(reflection_text)
            level_reflection_keys.append(reflection_key)

    metadata = {
        "run_dir": str(run_path),
        "history_k": history_k,
        "multi_action_history_k": multi_action_history_k,
        "level_action_history_max_rows": level_action_history_max_rows,
        "num_contexts": len([k for k in rendered if not k.endswith("_ma.md") and "_level_reflection_" not in k]),
        "num_multi_action_previews": len([k for k in rendered if k.endswith("_ma.md")]),
        "num_level_reflections": len(level_reflection_keys),
        "decision_steps": [batch.start_step for batch in batches],
        "multi_action_preview_steps": [
            step
            for batch in batches if batch.n_executed > 1
            for step in range(batch.start_step + 1, batch.end_step + 1)
        ],
        "level_reflection_steps": [
            {
                "step": int(step_log[int(key.split("_")[1])]["step"]),
                "level": int(key.split("_level_reflection_")[1].split(".")[0]),
                "file": key,
            }
            for key in level_reflection_keys
        ],
        "batches": [
            {
                "start_step": batch.start_step,
                "end_step": batch.end_step,
                "n_executed": batch.n_executed,
                "source": batch.source,
                "actions": batch.actions,
            }
            for batch in batches
        ],
    }
    (output_path / "metadata.json").write_text(json.dumps(metadata, indent=2))
    return rendered


