"""Register the packaged ARC-AGI-3 LLM profiles with Beam."""

from __future__ import annotations

from pathlib import Path

import yaml


_LLM_CONFIG_PATH = Path(__file__).with_name("llm_configs.yaml")
ARC3_LLM_CONFIGS = yaml.safe_load(
    _LLM_CONFIG_PATH.read_text(encoding="utf-8")
) or {}


# Optional short names accepted by TeamSolver's existing global --llm override.
LLM_SHORT_NAMES = {
    "opus-4.8": "arc3-opus-4.8",
    "opus-4.8-low": "arc3-opus-4.8-low",
    "gpt5.5": "arc3-gpt5.5",
    "gpt5.5-high": "arc3-gpt5.5-high",
    "flash": "arc3-flash",
}


# Pricing per 1M tokens: input, output, cache read, cache write.
_ANTHROPIC_OPUS = {
    "input": 5.0,
    "output": 25.0,
    "cached": 0.50,
    "cache_write": 6.25,
}
_OPENAI_GPT55 = {
    "input": 5.0,
    "output": 30.0,
    "cached": 0.50,
    "cache_write": 5.0,
}
_GEMINI_FLASH = {
    "input": 0.50,
    "output": 3.0,
    "cached": 0.05,
    "cache_write": 0.50,
}

LLM_PRICING = {
    "opus": _ANTHROPIC_OPUS,
    "gpt5.5": _OPENAI_GPT55,
    "flash": _GEMINI_FLASH,
}


def get_pricing(llm_key: str) -> dict:
    """Return per-million-token pricing for a short or ``arc3-*`` name."""
    pricing = LLM_PRICING.get(llm_key)
    if pricing:
        return pricing

    key = llm_key[5:] if llm_key.startswith("arc3-") else llm_key
    while key:
        pricing = LLM_PRICING.get(key)
        if pricing:
            return pricing
        if "-" not in key:
            break
        key = key.rsplit("-", 1)[0]

    return {"input": 0.0, "output": 0.0, "cached": 0.0}


# Retained for callers that display a selected profile by its short name.
LLM_DISPLAY_NAMES = {
    "opus-4.8": "Claude Opus 4.8",
    "opus-4.8-low": "Claude Opus 4.8 Low",
    "gpt5.5": "GPT-5.5",
    "gpt5.5-high": "GPT-5.5 High",
    "flash": "Gemini 3 Flash Preview",
}


def register_arc3_llms() -> dict[str, dict]:
    """Register the four packaged profiles and return their definitions."""
    from beam.chain.resource import register_chat_config

    for name, config in ARC3_LLM_CONFIGS.items():
        register_chat_config(name, config)
    return ARC3_LLM_CONFIGS


def create_llm(llm_key: str, reasoning_effort: str | None = None):
    """Create an LLM from a retained short name or a Beam URI/config name."""
    from beam.chain import beam_chain
    from beam.chain.resource import register_chat_config

    register_arc3_llms()

    if reasoning_effort and llm_key in LLM_SHORT_NAMES:
        config_name = LLM_SHORT_NAMES[llm_key]
        override_config = ARC3_LLM_CONFIGS[config_name].copy()
        override_config["reasoning_effort"] = reasoning_effort
        register_chat_config(config_name, override_config)

    if llm_key in LLM_SHORT_NAMES:
        return beam_chain(LLM_SHORT_NAMES[llm_key])
    return beam_chain(llm_key)

