"""Weighted-A* over the world model: f = g + W·h, h = 1 − progress(target).

`g` = action-steps so far. The heuristic is the IE's progress signal, which is
not provably admissible (it is a learned signal, can be non-monotone), so this
is weighted-A*/anytime: `weight=1` is plain A*, larger weights lean greedy. The
goal is tested on generation (find a solution fast); not guaranteed shortest.
"""

from __future__ import annotations

import heapq

from .base import Deadline, SearchBudget, SearchStats, WorldModelProblem, make_result


def astar(problem: WorldModelProblem, *, budget: SearchBudget | None = None, weight: float = 2.0):
    budget = budget or SearchBudget()
    stats = SearchStats()
    deadline = Deadline(budget)
    root = problem.root()
    if not problem.start_ready():
        return make_result(problem, root, 0.0, deadline, stats, "not_ready", ok=False)
    best, best_progress = root, problem.progress(root)
    if problem.is_goal(root):
        return make_result(problem, root, best_progress, deadline, stats, "goal_reached")

    seen = {root.key: 0}                       # key -> best g seen
    counter = 0
    heap = [(weight * (1.0 - best_progress), counter, root)]
    while heap and not deadline.expired(stats):
        _, _, node = heapq.heappop(heap)
        if node.depth >= budget.max_depth:
            continue
        for child in problem.expand(node, stats):
            if deadline.expired(stats):
                break
            g = child.depth
            if child.key in seen and seen[child.key] <= g:
                continue
            seen[child.key] = g
            progress = problem.progress(child)
            if progress > best_progress:
                best, best_progress = child, progress
            if problem.is_goal(child):
                stats.distinct_states = len(seen)
                return make_result(problem, child, progress, deadline, stats, "goal_reached")
            counter += 1
            f = g + weight * (1.0 - progress)
            heapq.heappush(heap, (f, counter, child))

    stats.distinct_states = len(seen)
    reason = ("timeout" if deadline.elapsed_ms() >= budget.wall_clock_ms
              else "frontier_empty" if not heap else "budget")
    return make_result(problem, best, best_progress, deadline, stats, reason)

