class HarnessFormatter:
    """Standardized formatting for harness-injected content.

    All harness-generated sections (middleware feedback, context blocks,
    REPL output) MUST use this instead of markdown headers so the LLM
    can distinguish harness metadata from user/file content.

    The ═══ delimiter is never produced by agent-written files, making
    it a reliable boundary marker.
    """

    DELIM = "═══"

    @classmethod
    def heading(cls, title: str) -> str:
        return f"{cls.DELIM} {title} {cls.DELIM}"

    @classmethod
    def heading_end(cls, title: str) -> str:
        return f"{cls.DELIM} END {title} {cls.DELIM}"

    @classmethod
    def warning(cls, title: str, detail: str) -> str:
        return f"{cls.DELIM} ⚠️ {title} {cls.DELIM}\n\n{detail}"

    @classmethod
    def error(cls, title: str, detail: str) -> str:
        return f"{cls.DELIM} ❌ {title} {cls.DELIM}\n\n{detail}"

    @classmethod
    def info(cls, title: str, detail: str) -> str:
        return f"{cls.DELIM} {title} {cls.DELIM}\n\n{detail}"

    @classmethod
    def file_section(cls, title: str, filename: str, content: str, suffix: str = "") -> str:
        return f"{cls.DELIM} {title} (`{filename}`){suffix} {cls.DELIM}\n\n{content}"

    @classmethod
    def file_section_empty(cls, title: str, filename: str, reason: str, suffix: str = "") -> str:
        return f"{cls.DELIM} {title} (`{filename}`){suffix} {cls.DELIM}\n*(empty — {reason})*"

    @classmethod
    def last_round_feedback(cls, content: str) -> str:
        return (
            f"{cls.heading('PREVIOUS STEP RESULTS')}\n"
            f"{content}\n"
            f"{cls.heading_end('PREVIOUS STEP RESULTS')}"
        )

    @classmethod
    def feedback(cls, parts: list[str]) -> str:
        body = "\n\n".join(parts)
        return (
            f"{cls.heading('SYSTEM FEEDBACK')}\n\n"
            f"{body}\n\n"
            f"{cls.heading_end('SYSTEM FEEDBACK')}"
        )

